function useReveal<T extends HTMLElement>() {
  const ref = useRef<T>(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    const observer = new IntersectionObserver(([entry]) => { if (entry.isIntersecting) { setVisible(true); observer.disconnect(); } }, { threshold: 0.12 });
    observer.observe(node);
    return () => observer.disconnect();
  }, []);
  return { ref, className: `reveal ${visible ? "is-visible" : ""}` };
}

function DragRail({ children, className = "" }: { children: ReactNode; className?: string }) {
  const ref = useRef<HTMLDivElement>(null); const [drag, setDrag] = useState(false); const start = useRef({ x: 0, left: 0 });
  return <div ref={ref} className={`drag-rail ${drag ? "is-dragging" : ""} ${className}`} onPointerDown={(e) => { if (!ref.current) return; setDrag(true); start.current = { x: e.clientX, left: ref.current.scrollLeft }; ref.current.setPointerCapture(e.pointerId); }} onPointerMove={(e) => { if (!drag || !ref.current) return; ref.current.scrollLeft = start.current.left - (e.clientX - start.current.x); }} onPointerUp={() => setDrag(false)} onPointerCancel={() => setDrag(false)}>{children}</div>;
}

